+        var(--instui-component-banner-close-button-margin-right)
+    );
+    color: var(--instui-component-banner-color);
+    background: var(--instui-component-banner-violet-background);
+
+    &::before,
+    &::after {
+      content: "";
+      position: absolute;
+      inset-block-start: var(--instui-component-banner-relaxed-padding-vertical);
+      inset-inline-start: var(--instui-component-banner-relaxed-padding-horizontal);
+      inline-size: var(--_banner-icon-size);
+      block-size: var(--_banner-icon-size);
+    }
+
+    &::before {
+      border-radius: var(--instui-component-banner-relaxed-icon-border-radius);
+      background: var(--_banner-icon-background);
+    }
+
+    &::after {
+      background: var(--instui-component-banner-icon-color);
+      mask: var(--instui-icon-megaphone) center / 1.125rem no-repeat;
+    }
+  }
+}
+
+[class~="instui-banner-sea"] {
+  --_banner-icon-background: var(--instui-component-banner-sea-icon-background);
+
